insert into public.question_translations (question_id, lang, prompt, options, explanation) values
  ('ng-ver-standalone-default', 'es', '¿Qué ha cambiado con `standalone` en las versiones recientes de Angular?', '["Se ha eliminado: ahora todos los componentes deben declararse siempre dentro de un NgModule","Es el valor por defecto: solo se escribe `standalone: false` para usar un NgModule","Solo funciona en componentes y no se puede usar en directivas ni en pipes","Hay que escribir `standalone: true` en cada componente, igual que desde la versión 14"]'::jsonb, 'Los componentes standalone aparecieron en Angular 14 y se volvieron estables en la 15. Desde **Angular 19 `standalone` es `true` por defecto**: ya no se escribe, y solo se indica `standalone: false` para un componente que siga declarado en un NgModule.'),
  ('ng-ver-standalone-default', 'en', 'What has changed about `standalone` in recent Angular versions?', '["It has been removed: now every component must always be declared inside an NgModule","It is the default: you only write `standalone: false` to use an NgModule","It only works on components and cannot be used on directives or pipes","You must write `standalone: true` on every component, as since version 14"]'::jsonb, 'Standalone components appeared in Angular 14 and became stable in 15. Since **Angular 19 `standalone` is `true` by default**: it is no longer written, and `standalone: false` is only given for a component still declared in an NgModule.'),
  ('ng-ver-bootstrap', 'es', '¿Qué sustituye a `platformBrowserDynamic().bootstrapModule(AppModule)` en una app standalone?', '["`bootstrapApplication(App, appConfig)`, que arranca el componente raíz","`ng.bootstrap(App)`, una función global que ofrece el navegador","`provideRouter(routes)`, que se encarga de arrancar toda la aplicación","`new App().start()`, porque el componente raíz se instancia a mano"]'::jsonb, 'En standalone no hay `AppModule`: `bootstrapApplication(App, appConfig)` arranca el componente raíz con la configuración (`providers`) de `app.config.ts`, en `main.ts`.'),
  ('ng-ver-bootstrap', 'en', 'What replaces `platformBrowserDynamic().bootstrapModule(AppModule)` in a standalone app?', '["`bootstrapApplication(App, appConfig)`, which bootstraps the root component","`ng.bootstrap(App)`, a global function offered by the browser","`provideRouter(routes)`, which takes care of starting the whole application","`new App().start()`, because the root component is instantiated by hand"]'::jsonb, 'In standalone there is no `AppModule`: `bootstrapApplication(App, appConfig)` bootstraps the root component with the configuration (`providers`) from `app.config.ts`, in `main.ts`.'),
  ('ng-ver-ngif-deprecated', 'es', '¿Qué estado tienen `*ngIf` y `*ngFor` en Angular 22?', '["Son la forma recomendada, y el control flow `@if` y `@for` es solo una alternativa experimental","Se han eliminado por completo y la aplicación no compila si se usan en una plantilla","Están obsoletos desde Angular 20 en favor de `@if` y `@for`, aunque aún funcionan","Solo se pueden usar en componentes con NgModules, y no en componentes standalone"]'::jsonb, '`NgIf` y `NgFor` están marcadas como obsoletas (`@deprecated 20.0`) a favor del **control flow** integrado: `@if`, `@for` y `@switch`, que llegó en Angular 17. Siguen funcionando, pero la migración se recomienda con `ng generate @angular/core:control-flow`.'),
  ('ng-ver-ngif-deprecated', 'en', 'What is the status of `*ngIf` and `*ngFor` in Angular 22?', '["They are the recommended way, and `@if` and `@for` control flow is only an experimental alternative","They have been removed entirely and the application does not compile if they are used in a template","They have been deprecated since Angular 20 in favor of `@if` and `@for`, though they still work","They can only be used in components with NgModules, and not in standalone components"]'::jsonb, '`NgIf` and `NgFor` are marked as deprecated (`@deprecated 20.0`) in favor of the built-in **control flow**: `@if`, `@for` and `@switch`, which arrived in Angular 17. They still work, but migration is recommended with `ng generate @angular/core:control-flow`.'),
  ('ng-ver-ngfor-to-for', 'es', '¿Cuál es el equivalente moderno de este `*ngFor`?

```html
<li *ngFor="let item of items; trackBy: trackById">
  {{ item.name }}
</li>
```', '["`@for (item of items) { <li>{{ item.name }}</li> }`, sin necesidad de `track`","`@for (item in items; trackBy trackById) { ... }`, cambiando `of` por `in`","`<li @for=\"item of items\">{{ item.name }}</li>`, como un atributo del elemento","`@for (item of items; track item.id) { <li>{{ item.name }}</li> }`"]'::jsonb, '`@for (item of items; track item.id) { ... }`. Dos diferencias: es un bloque con llaves (no un atributo) y **`track` es obligatorio**, y se escribe como una expresión (`track item.id`), no como una función `trackBy`.'),
  ('ng-ver-ngfor-to-for', 'en', 'What is the modern equivalent of this `*ngFor`?

```html
<li *ngFor="let item of items; trackBy: trackById">
  {{ item.name }}
</li>
```', '["`@for (item of items) { <li>{{ item.name }}</li> }`, with no need for `track`","`@for (item in items; trackBy trackById) { ... }`, changing `of` to `in`","`<li @for=\"item of items\">{{ item.name }}</li>`, as an attribute of the element","`@for (item of items; track item.id) { <li>{{ item.name }}</li> }`"]'::jsonb, '`@for (item of items; track item.id) { ... }`. Two differences: it is a block with braces (not an attribute) and **`track` is required**, written as an expression (`track item.id`), not a `trackBy` function.'),
  ('ng-ver-ngif-else', 'es', '¿Cuál es el equivalente moderno de este `*ngIf` con `else`?

```html
<p *ngIf="loaded; else loading">Listo</p>
<ng-template #loading><p>Cargando…</p></ng-template>
```', '["`@if (loaded) { <p>Listo</p> } else { <p>Cargando…</p> }`, con `else` sin arroba","`@if (loaded) { <p>Listo</p> } @else { <p>Cargando…</p> }`","`<p @if=\"loaded\">Listo</p> <p @else>Cargando…</p>`, con atributos","`@if loaded { <p>Listo</p> } @else { <p>Cargando…</p> }`, sin paréntesis"]'::jsonb, 'El control flow no necesita `ng-template`: `@if (cond) { ... } @else { ... }`, e incluso `@else if (otra) { ... }`. La condición va entre paréntesis y los bloques entre llaves, con la arroba también en `@else`.'),
  ('ng-ver-ngif-else', 'en', 'What is the modern equivalent of this `*ngIf` with `else`?

```html
<p *ngIf="loaded; else loading">Listo</p>
<ng-template #loading><p>Cargando…</p></ng-template>
```', '["`@if (loaded) { <p>Listo</p> } else { <p>Cargando…</p> }`, with `else` without the at-sign","`@if (loaded) { <p>Listo</p> } @else { <p>Cargando…</p> }`","`<p @if=\"loaded\">Listo</p> <p @else>Cargando…</p>`, with attributes","`@if loaded { <p>Listo</p> } @else { <p>Cargando…</p> }`, without parentheses"]'::jsonb, 'Control flow needs no `ng-template`: `@if (cond) { ... } @else { ... }`, and even `@else if (other) { ... }`. The condition goes in parentheses and the blocks in braces, with the at-sign on `@else` too.'),
  ('ng-ver-input-signal', 'es', '¿Cuál es el equivalente con signals de `@Input() name = '''';`?', '["`name = signal<string>('''')`, porque un signal ya recibe valores del padre","`name = model.input<string>('''')`, una función específica para inputs","`name = input<string>('''')`, y se lee como `name()`","`@Input() name = signal<string>('''')`, combinando el decorador y el signal"]'::jsonb, '`input<string>('''')` declara un input como **signal de solo lectura**; se lee con `name()`. `input.required<string>()` obliga al padre a pasarlo. Los signal inputs son estables desde Angular 19.'),
  ('ng-ver-input-signal', 'en', 'What is the signals equivalent of `@Input() name = '''';`?', '["`name = signal<string>('''')`, because a signal already receives values from the parent","`name = model.input<string>('''')`, a specific function for inputs","`name = input<string>('''')`, and it is read as `name()`","`@Input() name = signal<string>('''')`, combining the decorator and the signal"]'::jsonb, '`input<string>('''')` declares an input as a **read-only signal**; it is read with `name()`. `input.required<string>()` forces the parent to pass it. Signal inputs have been stable since Angular 19.'),
  ('ng-ver-output-function', 'es', '¿Cuál es el equivalente moderno de `@Output() saved = new EventEmitter<string>();`?', '["`saved = output<string>();`, que se emite con `saved.emit(valor)`","`saved = signal<string>('''');`, que se emite con `saved.set(valor)`","`saved = new Subject<string>();`, que se emite con `saved.next(valor)`","`@Output() saved = output<string>();`, manteniendo el decorador"]'::jsonb, '`output<string>()` sustituye a `@Output()` + `EventEmitter`. Se emite con `.emit(valor)` y el padre lo escucha igual: `(saved)="..."`. No depende de RxJS.'),
  ('ng-ver-output-function', 'en', 'What is the modern equivalent of `@Output() saved = new EventEmitter<string>();`?', '["`saved = output<string>();`, emitted with `saved.emit(value)`","`saved = signal<string>('''');`, emitted with `saved.set(value)`","`saved = new Subject<string>();`, emitted with `saved.next(value)`","`@Output() saved = output<string>();`, keeping the decorator"]'::jsonb, '`output<string>()` replaces `@Output()` + `EventEmitter`. It is emitted with `.emit(value)` and the parent listens the same way: `(saved)="..."`. It does not depend on RxJS.'),
  ('ng-ver-inject-function', 'es', '¿Qué es lo más habitual hoy en lugar de `constructor(private auth: AuthService) {}`?', '["`auth = new AuthService()`, creando el servicio en la propia clase","`private readonly auth = inject(AuthService);`","`auth = ng.get(AuthService)`, usando un inyector global de la ventana","`@Inject() auth: AuthService`, con un decorador en la propiedad"]'::jsonb, '`inject(AuthService)` (desde Angular 14) permite inyectar en inicializadores de propiedad, sin constructor. Es más corto, funciona en guards e interceptores funcionales y evita pasar dependencias con `super` en la herencia.'),
  ('ng-ver-inject-function', 'en', 'What is most common today instead of `constructor(private auth: AuthService) {}`?', '["`auth = new AuthService()`, creating the service in the class itself","`private readonly auth = inject(AuthService);`","`auth = ng.get(AuthService)`, using a global injector on the window","`@Inject() auth: AuthService`, with a decorator on the property"]'::jsonb, '`inject(AuthService)` (since Angular 14) lets you inject in property initializers, without a constructor. It is shorter, works in functional guards and interceptors and avoids passing dependencies through `super` in inheritance.'),
  ('ng-ver-functional-guard', 'es', '¿Qué devuelve este guard funcional para redirigir al usuario a `/login`?

```ts
export const authGuard: CanActivateFn = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  return auth.user() ? true : router.createUrlTree([''/login'']);
};
```', '["`false`, y Angular redirige al login automáticamente cuando un guard devuelve `false`","Una `Promise<void>` que se resuelve cuando el usuario ya ha iniciado sesión","Un `Observable<string>` con la ruta de destino a la que hay que navegar","Un `UrlTree`: la navegación se cancela y se redirige a la ruta indicada"]'::jsonb, 'Un guard puede devolver `true` (permitir), `false` (bloquear) o un **`UrlTree`** (cancelar y redirigir a esa ruta). Desde Angular 15 los guards son funciones (`CanActivateFn`) que usan `inject()`; los guards de clase (`implements CanActivate`) están obsoletos.'),
  ('ng-ver-functional-guard', 'en', 'What does this functional guard return to redirect the user to `/login`?

```ts
export const authGuard: CanActivateFn = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  return auth.user() ? true : router.createUrlTree([''/login'']);
};
```', '["`false`, and Angular redirects to login automatically when a guard returns `false`","A `Promise<void>` that resolves when the user has already signed in","An `Observable<string>` with the destination route to navigate to","A `UrlTree`: the navigation is cancelled and redirected to the given route"]'::jsonb, 'A guard can return `true` (allow), `false` (block) or a **`UrlTree`** (cancel and redirect to that route). Since Angular 15 guards are functions (`CanActivateFn`) that use `inject()`; class guards (`implements CanActivate`) are deprecated.'),
  ('ng-ver-http-client-module', 'es', '¿Qué sustituye a `HttpClientModule` en una app moderna?', '["`provideHttpClient()` en los `providers`, con funciones como `withInterceptors(...)`","`HttpModule`, el nuevo módulo de la versión 22 de `@angular/common`","Nada: `HttpClient` se inyecta sin registrar ningún proveedor en la aplicación","`provideFetch()`, que sustituye a todas las opciones de HTTP de Angular"]'::jsonb, '`HttpClientModule` está obsoleto. Se registra con `provideHttpClient()` en `app.config.ts`, y las funciones `with...` activan opciones: `withInterceptors`, `withFetch`, `withInterceptorsFromDi` (para interceptores de clase antiguos).'),
  ('ng-ver-http-client-module', 'en', 'What replaces `HttpClientModule` in a modern app?', '["`provideHttpClient()` in the `providers`, with functions such as `withInterceptors(...)`","`HttpModule`, the new module in version 22 of `@angular/common`","Nothing: `HttpClient` is injected without registering any provider in the application","`provideFetch()`, which replaces all of Angular''s HTTP options"]'::jsonb, '`HttpClientModule` is deprecated. It is registered with `provideHttpClient()` in `app.config.ts`, and the `with...` functions enable options: `withInterceptors`, `withFetch`, `withInterceptorsFromDi` (for old class interceptors).'),
  ('ng-ver-router-module', 'es', '¿Qué sustituye a `RouterModule.forRoot(routes)` en una app standalone?', '["`bootstrapApplication(routes)`, que arranca la aplicación con las rutas","`RouterModule.forRoutes(routes)`, que es el nombre actual de `forRoot`","`provideRouter(routes)` en los `providers` de `app.config.ts`","`@Routes(routes)`, un decorador que se aplica al componente raíz"]'::jsonb, '`provideRouter(routes, ...features)` registra el router sin módulos. Las opciones se añaden como funciones: `withComponentInputBinding()`, `withInMemoryScrolling()`, `withPreloading(...)`. Las rutas hijas se cargan con `loadChildren` o `loadComponent`.'),
  ('ng-ver-router-module', 'en', 'What replaces `RouterModule.forRoot(routes)` in a standalone app?', '["`bootstrapApplication(routes)`, which starts the application with the routes","`RouterModule.forRoutes(routes)`, which is the current name of `forRoot`","`provideRouter(routes)` in the `providers` of `app.config.ts`","`@Routes(routes)`, a decorator applied to the root component"]'::jsonb, '`provideRouter(routes, ...features)` registers the router without modules. Options are added as functions: `withComponentInputBinding()`, `withInMemoryScrolling()`, `withPreloading(...)`. Child routes are loaded with `loadChildren` or `loadComponent`.'),
  ('ng-ver-zonejs-default', 'es', '¿Qué ocurre con Zone.js en una aplicación nueva de Angular 22?', '["Se incluye siempre y es obligatorio: sin ella, la detección de cambios no funciona","No se incluye: la app es *zoneless* por defecto y se apoya en signals y eventos","Se incluye, pero desactivada hasta que se llama a `NgZone.enable()` en el arranque","Se sustituye por una versión nueva llamada `zone.js/next` que hay que instalar aparte"]'::jsonb, 'Una app nueva de Angular 22 **no lleva Zone.js**: es *zoneless*. La detección de cambios se dispara por signals leídos en la plantilla, eventos, `markForCheck()` y la pipe `async`. Quien lo necesite puede volver a activarla con `provideZoneChangeDetection()` y el polyfill.'),
  ('ng-ver-zonejs-default', 'en', 'What happens with Zone.js in a new Angular 22 application?', '["It is always included and mandatory: without it, change detection does not work","It is not included: the app is *zoneless* by default and relies on signals and events","It is included, but disabled until `NgZone.enable()` is called at startup","It is replaced by a new version called `zone.js/next` that must be installed separately"]'::jsonb, 'A new Angular 22 app **has no Zone.js**: it is *zoneless*. Change detection is triggered by signals read in the template, events, `markForCheck()` and the `async` pipe. Whoever needs it can turn it back on with `provideZoneChangeDetection()` and the polyfill.'),
  ('ng-ver-typed-forms', 'es', '¿Qué aportaron los formularios tipados de Angular 14?', '["La posibilidad de validar formularios en el servidor con los mismos tipos de TypeScript","Que los formularios dejaron de admitir valores `null` en cualquiera de sus controles","Un nuevo tipo de formulario llamado `TypedForm` que sustituye a `FormGroup`","`FormControl`, `FormGroup` y `FormArray` con tipos: `value` ya no es `any`"]'::jsonb, 'Antes de Angular 14, `form.value` era `any`. Con los formularios tipados, `FormControl<string | null>` o `FormGroup<{ name: FormControl<string> }>` dan autocompletado y errores de compilación. Existen `fb.nonNullable` y `UntypedFormGroup` para migrar.'),
  ('ng-ver-typed-forms', 'en', 'What did Angular 14''s typed forms bring?', '["The ability to validate forms on the server with the same TypeScript types","That forms stopped supporting `null` values in any of their controls","A new kind of form called `TypedForm` that replaces `FormGroup`","`FormControl`, `FormGroup` and `FormArray` with types: `value` is no longer `any`"]'::jsonb, 'Before Angular 14, `form.value` was `any`. With typed forms, `FormControl<string | null>` or `FormGroup<{ name: FormControl<string> }>` give autocompletion and compile errors. `fb.nonNullable` and `UntypedFormGroup` exist to ease migration.'),
  ('ng-ver-esbuild-builder', 'es', '¿Qué builder usan por defecto los proyectos Angular nuevos para compilar la aplicación?', '["`@angular-devkit/build-angular:browser`, basado en Webpack, como siempre","`@angular/build:vite`, que solo sirve para el servidor de desarrollo","`@angular/build:application`, basado en esbuild y Vite","`@angular/build:rollup`, un empaquetador pensado para librerías de componentes"]'::jsonb, '`@angular/build:application` usa **esbuild** para compilar y Vite para el servidor de desarrollo, con compilaciones mucho más rápidas que el antiguo builder de Webpack. Es el que aparece en el `angular.json` de este proyecto.'),
  ('ng-ver-esbuild-builder', 'en', 'Which builder do new Angular projects use by default to build the application?', '["`@angular-devkit/build-angular:browser`, Webpack-based, as always","`@angular/build:vite`, which only serves the dev server","`@angular/build:application`, based on esbuild and Vite","`@angular/build:rollup`, a bundler designed for component libraries"]'::jsonb, '`@angular/build:application` uses **esbuild** to build and Vite for the dev server, with much faster builds than the old Webpack builder. It is the one in this project''s `angular.json`.'),
  ('ng-ver-test-runner', 'es', '¿Qué ejecutor de tests usan por defecto los proyectos Angular nuevos?', '["Vitest, con el builder `@angular/build:unit-test`, en lugar de Karma y Jasmine","Karma con Jasmine, como en todas las versiones desde que existe la CLI","Jest, que se instala automáticamente al ejecutar `ng new` en cualquier versión","Ninguno: la CLI ya no incluye ninguna herramienta para escribir pruebas"]'::jsonb, 'Los proyectos nuevos usan **Vitest** con el builder `@angular/build:unit-test` (`ng test`), sustituyendo a Karma y Jasmine. En este proyecto aparece como `vitest` en `package.json`. Los tests usan `describe`, `it` y `expect`, como en Jest.'),
  ('ng-ver-test-runner', 'en', 'Which test runner do new Angular projects use by default?', '["Vitest, with the `@angular/build:unit-test` builder, instead of Karma and Jasmine","Karma with Jasmine, as in every version since the CLI exists","Jest, which is installed automatically when running `ng new` in any version","None: the CLI no longer includes any tool for writing tests"]'::jsonb, 'New projects use **Vitest** with the `@angular/build:unit-test` builder (`ng test`), replacing Karma and Jasmine. In this project it appears as `vitest` in `package.json`. Tests use `describe`, `it` and `expect`, as in Jest.'),
  ('ng-ver-file-naming', 'es', '¿Cómo se nombran los ficheros y las clases de los componentes que genera la CLI en las versiones recientes?', '["`app.component.ts` con la clase `AppComponent`, como siempre","`app.ts` con la clase `App`, sin sufijos","`app.cmp.ts` con la clase `AppCmp`, con un sufijo más corto","`App.tsx` con la clase `App`, igual que en React"]'::jsonb, 'Desde la guía de estilo de Angular 20, la CLI genera `app.ts` y la clase `App`: sin el sufijo `.component`. Es una convención, no una obligación, pero conviene mantener la misma en todo el proyecto.'),
  ('ng-ver-file-naming', 'en', 'How are the files and classes of components generated by the CLI named in recent versions?', '["`app.component.ts` with the class `AppComponent`, as always","`app.ts` with the class `App`, without suffixes","`app.cmp.ts` with the class `AppCmp`, with a shorter suffix","`App.tsx` with the class `App`, just like in React"]'::jsonb, 'Since the Angular 20 style guide, the CLI generates `app.ts` and the class `App`: without the `.component` suffix. It is a convention, not an obligation, but it is best to keep the same one across the whole project.'),
  ('ng-ver-let-syntax', 'es', '¿Para qué sirve `@let` en una plantilla?

```html
@let total = price() * quantity();
<p>Total: {{ total }}</p>
```', '["Para declarar una variable de la clase del componente desde la plantilla","Para importar una función de otro fichero y usarla en el HTML","Para declarar una variable local en la plantilla, evaluada de forma reactiva","Para crear un bloque que se ejecuta solo una vez al renderizar la plantilla"]'::jsonb, '`@let` declara una **variable local de plantilla**: `@let total = price() * quantity();`. Se recalcula cuando cambian los signals que lee y se puede usar más abajo en esa plantilla. Evita repetir una expresión o envolverla en `@if (...; as x)`.'),
  ('ng-ver-let-syntax', 'en', 'What is `@let` for in a template?

```html
@let total = price() * quantity();
<p>Total: {{ total }}</p>
```', '["To declare a component class variable from the template","To import a function from another file and use it in the HTML","To declare a local variable in the template, evaluated reactively","To create a block that runs only once when the template renders"]'::jsonb, '`@let` declares a **local template variable**: `@let total = price() * quantity();`. It recomputes when the signals it reads change and can be used further down that template. It avoids repeating an expression or wrapping it in `@if (...; as x)`.'),
  ('ng-ver-viewchild-signal', 'es', '¿Cuál es el equivalente con signals de `@ViewChild(''box'') box!: ElementRef;`?', '["`box = signal<ElementRef>(''box'')`, que busca el elemento por su nombre","`box = view<ElementRef>(''box'')`, una función específica para vistas","`@ViewChild(''box'') box = signal<ElementRef>()`, combinando decorador y signal","`box = viewChild<ElementRef>(''box'')`, y se lee como `box()`"]'::jsonb, '`viewChild<ElementRef>(''box'')` devuelve un **signal** con el elemento (o `undefined` si no existe). Se lee con `box()`, se puede usar en `computed` y `effect`, y `viewChild.required` falla si no lo encuentra. Existen también `viewChildren`, `contentChild` y `contentChildren`.'),
  ('ng-ver-viewchild-signal', 'en', 'What is the signals equivalent of `@ViewChild(''box'') box!: ElementRef;`?', '["`box = signal<ElementRef>(''box'')`, which looks up the element by its name","`box = view<ElementRef>(''box'')`, a specific function for views","`@ViewChild(''box'') box = signal<ElementRef>()`, combining decorator and signal","`box = viewChild<ElementRef>(''box'')`, and it is read as `box()`"]'::jsonb, '`viewChild<ElementRef>(''box'')` returns a **signal** with the element (or `undefined` if missing). It is read with `box()`, can be used in `computed` and `effect`, and `viewChild.required` fails if it cannot find it. `viewChildren`, `contentChild` and `contentChildren` also exist.'),
  ('ng-ver-onchanges-to-computed', 'es', 'Con signal inputs, ¿cómo se suele reaccionar a un cambio de input en lugar de usar `ngOnChanges`?', '["Con un `setInterval` que compare el valor del input con el anterior cada segundo","Con un `computed` para derivar valores o un `effect` para ejecutar una acción","Con `@HostListener(''change'')`, que escucha los cambios de los inputs del componente","No se puede: los signal inputs no permiten reaccionar a sus cambios de ninguna forma"]'::jsonb, 'Un `input()` es un signal: si quieres **derivar** un valor, usas `computed(() => this.name().toUpperCase())`; si quieres **hacer algo** al cambiar, un `effect`. `ngOnChanges` sigue funcionando, pero con signals rara vez hace falta.'),
  ('ng-ver-onchanges-to-computed', 'en', 'With signal inputs, how do you usually react to an input change instead of using `ngOnChanges`?', '["With a `setInterval` that compares the input value with the previous one every second","With a `computed` to derive values or an `effect` to run an action","With `@HostListener(''change'')`, which listens to the component''s input changes","You cannot: signal inputs do not allow reacting to their changes in any way"]'::jsonb, 'An `input()` is a signal: if you want to **derive** a value, you use `computed(() => this.name().toUpperCase())`; if you want to **do something** on change, an `effect`. `ngOnChanges` still works, but with signals it is rarely needed.'),
  ('ng-ver-signals-intro', 'es', '¿En qué versión de Angular se introdujeron los signals?', '["En Angular 16, como vista previa para desarrolladores","En Angular 8, junto con la compilación con Ivy","En Angular 12, con la llegada de los componentes standalone","En Angular 22, junto con la eliminación de Zone.js"]'::jsonb, 'Los signals llegaron en **Angular 16** (2023) como *developer preview*, y se han ido estabilizando en versiones posteriores (`signal`, `computed` y los signal inputs primero; `effect` y los formularios con signals, después). Son la base del Angular zoneless.'),
  ('ng-ver-signals-intro', 'en', 'In which Angular version were signals introduced?', '["In Angular 16, as a developer preview","In Angular 8, along with Ivy compilation","In Angular 12, with the arrival of standalone components","In Angular 22, along with the removal of Zone.js"]'::jsonb, 'Signals arrived in **Angular 16** (2023) as a *developer preview*, and have stabilized in later versions (`signal`, `computed` and signal inputs first; `effect` and signal-based forms, later). They are the foundation of zoneless Angular.'),
  ('ng-ver-support-policy', 'es', '¿Cada cuánto sale una versión mayor de Angular y cuánto dura su soporte?', '["Una versión mayor cada año, con soporte de 5 años para cada una","Una versión mayor cada 3 meses, con soporte de solo 3 meses","Una versión mayor cada 2 años, con soporte de 6 meses cada una","Una versión mayor cada 6 meses, con 18 meses de soporte en total"]'::jsonb, 'Angular publica una versión **mayor cada 6 meses** (normalmente mayo y noviembre). Cada una tiene **18 meses de soporte**: 6 de soporte activo y 12 de soporte a largo plazo (LTS) con correcciones críticas. Para actualizar se usa `ng update`, versión a versión.'),
  ('ng-ver-support-policy', 'en', 'How often does a major Angular version come out and how long is it supported?', '["A major version every year, with 5 years of support for each","A major version every 3 months, with only 3 months of support","A major version every 2 years, with 6 months of support each","A major version every 6 months, with 18 months of support in total"]'::jsonb, 'Angular releases a **major version every 6 months** (usually May and November). Each has **18 months of support**: 6 of active support and 12 of long-term support (LTS) with critical fixes. To upgrade, `ng update` is used, version by version.')
on conflict (question_id, lang) do update set
    prompt = excluded.prompt,
    options = excluded.options,
    explanation = excluded.explanation;
